var e=document.querySelector(`[data-commission-chart]`);if(e&&window.ApexCharts){let t=JSON.parse(e.dataset.commissions||`[]`),n=JSON.parse(e.dataset.orders||`[]`);t.length?new ApexCharts(document.getElementById(`commissionChart`),{chart:{type:`bar`,height:280,toolbar:{show:!1}},series:[{name:`Commission (₱)`,data:t}],xaxis:{categories:n},colors:[`#E8472A`],dataLabels:{enabled:!1},plotOptions:{bar:{borderRadius:4}}}).render():document.getElementById(`commissionChart`).innerHTML=`<p style="text-align:center;color:#aaa;padding:2rem;">No data available</p>`}